// src/utils/cx.ts
function cx(...parts) {
  return parts.filter(Boolean).join(" ");
}

// src/components/BrandMark/BrandMark.tsx
import { jsx } from "react/jsx-runtime";
function BrandMark({ letter = "Z", className }) {
  return /* @__PURE__ */ jsx("span", { className: cx("hds-zmark", className), children: /* @__PURE__ */ jsx("span", { children: letter }) });
}

